// Publication dataset of the facts register v1.2 (D1); OC-02 follows v1.6, and the learner stories ST-01, ST-02 and ST-05 name the learner exactly as the previous coderstrust.global site did (owner statement OWNER-2026-10-11-OLDSITE: permission from all trainees and learners; WP2b). Only V facts and R facts with a public scope (`allow`) are included; U facts and never-publish R facts stay in the private register. Wording and status are canonical; the figures are stated plainly (WP9b).
// Everything exported here can be rendered on a public page: no internal notes live in this file, and
// facts that must never be published (unverified or never-publish restricted items) stay in the private register.
// Citations (D16) are public or primary only and are internal provenance: no page prints a source list (WP9a). The status gate (D15) is enforced by scripts/check-facts.mjs.
/** V verified · U unverified (blocked outside /news/) · R restricted (only on the paths in `allow`). */
export type FactStatus = 'V' | 'U' | 'R';
export interface Source { id: string; label: string; citation: string; url?: string }
export interface StatDisplay {
  value: string; numeric?: number; decimals?: number; prefix?: string; suffix?: string; from?: string; label: string;
  /** A short line shown under the tile's label (provenance, scope or composition the label has no room for); <FactStat> renders it as the tile's note. */
  detail?: string;
  /** Short tile wording for the At a Glance strips (<GlanceBand>): a shorter label and a one-line note; the tile falls back to `label` and none. */
  glance?: { label: string; note?: string };
}
export interface Fact {
  id: string;
  group: 'identity' | 'scale' | 'outcomes' | 'rct' | 'programs' | 'stories' | 'government' | 'partners' | 'design' | 'initiatives' | 'context' | 'admissions';
  status: FactStatus;
  text: string;
  /** Alternative public headline wording (authoritative copy), where the register brief defines one. */
  headline?: string;
  stat?: StatDisplay;
  sourceIds: string[];
  /** R facts only: path prefixes (site-relative, e.g. "/news/") where the fact may render. Empty/absent = nowhere. */
  allow?: string[];
}

/**
 * Messaging framework rule 13 (F1, M2): vendor certifications are named only with this note, once, beside the first naming on a page.
 * `CERT_FACT_IDS` are the facts whose text names vendor certifications; `<CertNote>` renders the note and `<Fact>` adds it automatically.
 * scripts/check-facts.mjs fails the build for any page that names a vendor certification without the note, and for any page that prints it twice.
 */
export const CERT_NOTE_TEXT = `CodersTrust is not affiliated with or endorsed by these certifying bodies; it prepares learners for their exams.`;
export const CERT_FACT_IDS: readonly string[] = ['PD-03', 'IN-08'];

